mapper.select:
SELECT 
FROM adoption_application a
LEFT JOIN pet p ON p.id = a.pet_id AND p.deleted = 0
LEFT JOIN `user` u ON u.id = a.user_id AND u.deleted = 0
LEFT JOIN shelter s ON s.id = a.shelter_id AND s.deleted = 0

    a.deleted = 0
    AND a.user_id = #{q.userId}
    AND a.status = #{q.status}
    AND a.pet_id = #{q.petId}

ORDER BY a.create_time DESC, a.id DESC
